#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MiniCut Patch 37 - ChatGPT update (filter keyframes on the timeline, HW decode checks, render diagnostics)

* Registers the files that the ChatGPT update changed by hand (effect keyframe evaluation, keyframe markers on the timeline, Key all buttons, validated GPU decode, preview-request savings, render diagnostics), so the Launcher can place every older update in the history instead of showing 'conflict'.
* If your folder already contains the ChatGPT update this one shows as installed and changes nothing. On a Patch 31 folder it installs those files (after Patch 32, 33 and 35).
* Known issue of that update, fixed by Patch 38: effects were skipped between two keyframes.

Files changed: minicut/app.py, minicut/render/effects.py, minicut/render/fxpack/kit.py, minicut/render/gpu.py, minicut/render/media.py, minicut/render/renderer.py, minicut/shared/dialogs.py, minicut/workspace/effects_panel.py, minicut/workspace/preview_widgets.py, minicut/workspace/timeline.py
  python Patch/apply_37_chatgpt_update.py --check      (look only, change nothing)
  python Patch/apply_37_chatgpt_update.py              (install)
  python Patch/apply_37_chatgpt_update.py --revert     (put the files back from the backup)
Close MiniCut before installing. The MiniCut Launcher can do all of this for you.
"""
import base64, datetime, hashlib, json, os, py_compile, shutil, sys, zlib
PATCH_NAME = "patch37_chatgpt_update"
REPLACE = {'minicut/app.py': {'base': 'f047b1193ae9590c7cbe5cc57b85d012a919157b5c7ad9dc14c8628a5bb5e9b4', 'new': 'f79b84c69783ca2c612b11d9c6e82d0ea0b88044a43ca2fa19940704a585a222'}, 'minicut/render/effects.py': {'base': 'c21814d40168a11f04a071e6349efea3878c78add240b80bdf176addadeaf2cb', 'new': 'dedcfaf2f690cac6726d3faa61053a564eb781987c6b64d48686afce7ad7454e'}, 'minicut/render/fxpack/kit.py': {'base': '39549d4d5eeecf6bb30e04f15395da20953d33393e893b7c1b38f6855ac249e7', 'new': '1e51c29cefdf54a77ec6aedd420c58e5418115a292e6ad51772870c710bd2bb6'}, 'minicut/render/gpu.py': {'base': 'ebdea6a1a2f01f056ad9d2423f34779873142b07677060de867039903eec3433', 'new': '37fdfcf4ea482352423b9b3b178e72242151522db109e1b1ea0fb12fad961559'}, 'minicut/render/media.py': {'base': '3e9bc3e1da0e5afac8eca1afc7167a05bd3dde1cc9d9a155c77a95bb457612f4', 'new': 'ee5bbdbad285a12bf31283c55fbff40a68206c1d8fae4dde963051fbe3462e8a'}, 'minicut/render/renderer.py': {'base': '22c37fa23277d827c14cd2a815fca4ffc7a51ddea9702742661ff7f4e09e4568', 'new': 'c947ba3cfcb878f27ec2834420a7ac887b2f6f81d5104fb8e55b873429488ae4'}, 'minicut/shared/dialogs.py': {'base': '25e1fb0b826f4fe6f22837d45e035964eaaa642124f9bbb1554eb75652188336', 'new': 'd106c3f5fd6ade703f719351e1aa1cc77e14e393f154695a3207e8fbdef9f4fd'}, 'minicut/workspace/effects_panel.py': {'base': 'a90ac7db239174ff2c452352e58c4f239387f28374ae9af0e9de2ea217477393', 'new': '05f21c11934ac86de080629c56f08d25332dceab646cb68ecad2cd566cfd26f9'}, 'minicut/workspace/preview_widgets.py': {'base': '908d3dc3e1295b222325d1e16cadd093b35ad3f659350e69c0d7e58e8439d255', 'new': '7a7e76e02a9196bce41289401ae77638b21d4c21ac2758d7aacbdae148b71c3a'}, 'minicut/workspace/timeline.py': {'base': '62114dadf9dd98b8b0aa818f5ccf098fd57454750b179c58490ebdcfaf80f6a1', 'new': '8e41f9790d8da13035f62b5ef8d2b92f4d11e17d9b89a168abf465d1507b67c2'}}
NEW_FILES = {}
PAYLOAD = {'minicut/app.py': '', 'minicut/render/effects.py': '', 'minicut/render/fxpack/kit.py': '', 'minicut/render/gpu.py': '', 'minicut/render/media.py': '', 'minicut/render/renderer.py': '', 'minicut/shared/dialogs.py': '', 'minicut/workspace/effects_panel.py': '', 'minicut/workspace/preview_widgets.py': '', 'minicut/workspace/timeline.py': ''}
HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = HERE if os.path.isfile(os.path.join(HERE, "minicut", "app.py")) else (os.path.dirname(HERE) if os.path.isfile(os.path.join(os.path.dirname(HERE), "minicut", "app.py")) else HERE)
BACKUP_ROOT = os.path.join(ROOT, "_patch_backup")


def norm_hash(b): return hashlib.sha256(b.replace(b"\r\n", b"\n")).hexdigest()
def path_of(rel): return os.path.join(ROOT, *rel.split("/"))
def read(rel):
    try:
        with open(path_of(rel), "rb") as f: return f.read()
    except OSError: return None
def new_bytes(rel):
    return zlib.decompress(base64.b64decode(PAYLOAD[rel]))
def latest_backup():
    found = []
    if os.path.isdir(BACKUP_ROOT):
        for d in os.listdir(BACKUP_ROOT):
            mf = os.path.join(BACKUP_ROOT, d, "MANIFEST.json")
            if os.path.isfile(mf):
                try:
                    with open(mf, encoding="utf-8") as f:
                        if json.load(f).get("patch") == PATCH_NAME: found.append(d)
                except Exception: pass
    return os.path.join(BACKUP_ROOT, sorted(found)[-1]) if found else None


def revert():
    bdir = latest_backup()
    if not bdir: print("No backup of this update was found."); return 1
    with open(os.path.join(bdir, "MANIFEST.json"), encoding="utf-8") as f: m = json.load(f)
    for rel in m.get("replaced", []): shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
    for rel in m.get("created", []):
        try: os.remove(path_of(rel))
        except OSError: pass
    os.replace(os.path.join(bdir, "MANIFEST.json"), os.path.join(bdir, "MANIFEST.undone.json"))
    print("Reverted from backup:", bdir); return 0


def main():
    if not os.path.isfile(os.path.join(ROOT, "minicut", "app.py")):
        print("ERROR: the MiniCut folder was not found. Put this file in MiniCut/Patch/ (or next to the minicut folder)."); return 2
    if "--revert" in sys.argv: return revert()
    todo_replace, todo_new, already = [], [], 0
    for rel, h in REPLACE.items():
        cur = read(rel)
        if cur is None: print("STOPPED: missing file", rel, "- no files were changed."); return 3
        c = norm_hash(cur)
        if c == h["new"]: already += 1
        elif c == h["base"]: todo_replace.append(rel)
        else:
            print("STOPPED:", rel, "is not the version this update expects (it was changed by hand or by another update).")
            print("No files were changed. This protects your own edits."); return 3
    for rel, text in NEW_FILES.items():
        cur = read(rel)
        if cur is None: todo_new.append(rel)
        elif norm_hash(cur) == norm_hash(text.encode("utf-8")): already += 1
        else: print("STOPPED:", rel, "already exists with other content. No files were changed."); return 3
    if not todo_replace and not todo_new: print("This update is already installed."); return 0
    if "--check" in sys.argv:
        print("Check passed. Would change:", ", ".join(todo_replace + todo_new)); return 0
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S"); bdir = os.path.join(BACKUP_ROOT, stamp); k = 1
    while os.path.exists(bdir): k += 1; bdir = os.path.join(BACKUP_ROOT, "%s_%d" % (stamp, k))      # two installs in one second
    os.makedirs(bdir, exist_ok=False)
    for rel in todo_replace:
        dst = os.path.join(bdir, *rel.split("/")); os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy2(path_of(rel), dst)
    with open(os.path.join(bdir, "MANIFEST.json"), "w", encoding="utf-8") as f:
        json.dump({"patch": PATCH_NAME, "created": todo_new, "replaced": todo_replace}, f, indent=2)
    try:
        for rel in todo_replace:
            cur = read(rel); data = new_bytes(rel).replace(b"\r\n", b"\n")
            if b"\r\n" in cur: data = data.replace(b"\n", b"\r\n")            # keep the file's own line endings
            with open(path_of(rel), "wb") as f: f.write(data)
            if norm_hash(read(rel)) != REPLACE[rel]["new"]: raise RuntimeError("hash mismatch after writing " + rel)
        for rel in todo_new:
            os.makedirs(os.path.dirname(path_of(rel)), exist_ok=True)
            with open(path_of(rel), "wb") as f: f.write(NEW_FILES[rel].encode("utf-8"))
        for rel in todo_replace + todo_new:
            if rel.endswith(".py"): py_compile.compile(path_of(rel), doraise=True)
    except Exception as ex:
        for rel in todo_replace: shutil.copy2(os.path.join(bdir, *rel.split("/")), path_of(rel))
        for rel in todo_new:
            try: os.remove(path_of(rel))
            except OSError: pass
        print("ERROR: the update failed and every file was put back:", repr(ex)); return 1
    print("Installed Patch 37. Changed:", ", ".join(todo_replace + todo_new)); print("Backup:", bdir); return 0


if __name__ == "__main__":
    try: code = main()
    except Exception as ex: print("Unexpected error:", repr(ex)); code = 1
    sys.exit(code)
